var g errgroup.Group
outs := make([]struct{ v int; err error }, len(inputs))
for i, in := range inputs {                 // independent inputs
    i, in := i, in
    g.Go(func() error {
        outs[i].v, outs[i].err = parse(in)  // distinct index: race-free
        return nil                          // return err => fail-fast instead
    })
}
if err := g.Wait(); err != nil { return 0, err }
return combine(outs), errors.Join(errsOf(outs)...)
